    private final BroadcastReceiver progressReceiver = new BroadcastReceiver() { @Override public void onReceive(Context context, Intent intent) { if (PlaybackService.ACTION_PROGRESS.equals(intent.getAction())) { int position=intent.getIntExtra("position",0), duration=intent.getIntExtra("duration",0); boolean playing=intent.getBooleanExtra("playing",false); String uri=intent.getStringExtra("uri"); int previousIndex=playingIndex; if(uri!=null&&!uri.isEmpty()){for(int i=0;i<tracks.size();i++){if(uri.equals(tracks.get(i).uri)){playingIndex=i;updateMiniTrackViews(tracks.get(i));break;}}} updatePlaybackUi(playing); if(page==4&&previousIndex!=playingIndex&&currentTrack()!=null)renderPlayer(); if(playerProgress!=null&&!userSeeking&&duration>0) playerProgress.setProgress((int)(position*1000L/duration)); updateLyrics(position); } } };
    @Override public void onCreate(Bundle state) { super.onCreate(state); darkMode=getSharedPreferences("mintune_settings",MODE_PRIVATE).getBoolean("dark_mode",true); applyThemePalette(); if (Build.VERSION.SDK_INT >= 30) getWindow().setDecorFitsSystemWindows(true); getWindow().setStatusBarColor(BG); getWindow().setNavigationBarColor(BG); database = new LibraryDbHelper(this); android.content.IntentFilter progressFilter = new android.content.IntentFilter(PlaybackService.ACTION_PROGRESS); if (Build.VERSION.SDK_INT >= 33) registerReceiver(progressReceiver, progressFilter, Context.RECEIVER_NOT_EXPORTED); else registerReceiver(progressReceiver, progressFilter); buildShell(); if (hasAudioPermission()) loadData(); else requestAudioPermission(); }
