    private void renderPlayer() { LinearLayout top=row(); top.setGravity(Gravity.CENTER_VERTICAL); Button back=button("‹"); back.setTextSize(24); back.setTextColor(TEXT); back.setBackgroundColor(Color.TRANSPARENT); back.setElevation(0); back.setOnClickListener(v->switchPage(previousPage)); top.addView(back,lp(dp(44),dp(42))); TextView label=text("播放详情",17,TEXT); label.setGravity(Gravity.CENTER_VERTICAL); top.addView(label,lp(0,dp(42),1)); Button more=button("•••"); more.setTextSize(18); more.setTextColor(TEXT); more.setBackgroundColor(Color.TRANSPARENT); more.setElevation(0); more.setOnClickListener(v->{if(currentTrack()!=null)showTrackMenu(currentTrack());}); top.addView(more,lp(dp(48),dp(42))); pageHost.addView(top,lp(-1,dp(46))); LibraryDbHelper.Track track=currentTrack(); if(track==null){pageHost.addView(text("还没有正在播放的歌曲",16,MUTED),lp(-1,dp(160)));return;} ScrollView scroll=new ScrollView(this); scroll.setClipToPadding(false); final float[] pageSwipeStart={0f}; scroll.setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN){pageSwipeStart[0]=event.getX();v.getParent().requestDisallowInterceptTouchEvent(true);}else if(event.getAction()==MotionEvent.ACTION_UP){v.getParent().requestDisallowInterceptTouchEvent(false);if(event.getX()-pageSwipeStart[0]>dp(70)&&page==4){switchPage(6);return true;}}return false;}); LinearLayout body=column(); body.setGravity(Gravity.CENTER_HORIZONTAL); body.setPadding(dp(18),dp(12),dp(18),dp(24)); body.setBackgroundColor(BG); ImageView cover=new ImageView(this); cover.setScaleType(ImageView.ScaleType.CENTER_CROP); cover.setBackground(glassBackground(ALT,dp(18))); cover.setClipToOutline(true); cover.setClickable(true); cover.setElevation(dp(8)); final float[] swipeStartX={0f}; cover.setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN){swipeStartX[0]=event.getX();v.getParent().requestDisallowInterceptTouchEvent(true);return true;}if(event.getAction()==MotionEvent.ACTION_UP){v.getParent().requestDisallowInterceptTouchEvent(false);if(event.getX()-swipeStartX[0]>dp(60)){switchPage(6);return true;}}return true;}); loadCover(cover,track); body.addView(cover,lp(dp(270),dp(270))); TextView title=text(track.title,21,TEXT); title.setGravity(Gravity.CENTER); title.setTypeface(null,1); title.setMaxLines(1); title.setEllipsize(android.text.TextUtils.TruncateAt.END); LinearLayout.LayoutParams titleParams=lp(-1,dp(38));titleParams.setMargins(dp(8),dp(18),dp(8),0);body.addView(title,titleParams); TextView meta=text(track.artist+" · "+track.album,14,MUTED); meta.setGravity(Gravity.CENTER); meta.setMaxLines(1); meta.setEllipsize(android.text.TextUtils.TruncateAt.END); body.addView(meta,lp(-1,dp(28))); playerProgress=new SeekBar(this); playerProgress.setMax(1000); playerProgress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean fromUser){} public void onStartTrackingTouch(SeekBar bar){userSeeking=true;} public void onStopTrackingTouch(SeekBar bar){userSeeking=false;startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_SEEK).putExtra("progress",bar.getProgress()));}}); LinearLayout.LayoutParams seekParams=lp(-1,dp(38));seekParams.setMargins(0,dp(10),0,dp(2));body.addView(playerProgress,seekParams); LinearLayout controls=row(); controls.setGravity(Gravity.CENTER); Button previous=lightPlayerButton("|‹"); previous.setOnClickListener(v->startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_PREVIOUS))); Button pause=lightPlayerButton("▶"); detailToggle=pause; pause.setTextSize(28); pause.setTextColor(TEXT); pause.setOnClickListener(v->startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_TOGGLE))); Button next=lightPlayerButton("›|"); next.setOnClickListener(v->startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_NEXT))); controls.addView(previous,lp(dp(64),dp(58))); controls.addView(pause,lp(dp(78),dp(64))); controls.addView(next,lp(dp(64),dp(58))); LinearLayout.LayoutParams controlsParams=lp(-1,dp(76));controlsParams.setMargins(0,dp(6),0,dp(8));body.addView(controls,controlsParams); LinearLayout tools=row(); tools.setGravity(Gravity.CENTER); String[] toolLabels={"↻","◷","词","☷","•••"}; for(String labelText:toolLabels){Button tool=lightPlayerButton(labelText); tool.setTextSize(18); if("词".equals(labelText))tool.setOnClickListener(v->switchPage(6)); else if("☷".equals(labelText))tool.setOnClickListener(v->switchPage(5)); else if("•••".equals(labelText))tool.setOnClickListener(v->{if(currentTrack()!=null)showTrackMenu(currentTrack());}); tools.addView(tool,lp(0,dp(42),1));} LinearLayout.LayoutParams toolsParams=lp(-1,dp(48));toolsParams.setMargins(0,dp(2),0,dp(14));body.addView(tools,toolsParams); scroll.addView(body); pageHost.addView(scroll,lp(-1,0,1)); }
