        activeLyrics=null; currentLyrics=new ArrayList<>(); if(track.lrcPath==null){addLyricPlaceholder("暂无歌词", "可将同名 .lrc 文件放在音频文件旁边");return;} executor.execute(()->{try{String content=new String(java.nio.file.Files.readAllBytes(new File(track.lrcPath).toPath()),java.nio.charset.StandardCharsets.UTF_8);List<LrcParser.Line> parsed=LrcParser.parse(content);runOnUiThread(()->{currentLyrics=parsed;if(parsed.isEmpty())addLyricPlaceholder("暂无歌词", "可将同名 .lrc 文件放在音频文件旁边");else{activeLyricLine=-1;updateLyrics(0);}});}catch(Exception ignored){runOnUiThread(()->addLyricPlaceholder("歌词读取失败", "请检查 LRC 文件编码和内容"));}});
