    private android.app.Dialog glassDialog(String title){android.app.Dialog dialog=new android.app.Dialog(this);LinearLayout panel=card();panel.setPadding(dp(20),dp(16),dp(20),dp(16));TextView heading=text(title,19,TEXT);heading.setTypeface(null,1);panel.addView(heading);dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setDimAmount(.58f);dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);}return dialog;}
