        search=new EditText(this);search.setHint("搜索歌曲、艺人或专辑");search.setTextColor(TEXT);search.setHintTextColor(MUTED);search.setTextSize(15);search.setSingleLine(true);search.setInputType(InputType.TYPE_CLASS_TEXT);search.setPadding(dp(14),0,dp(12),0);search.setBackground(glassBackground(SURFACE,dp(13)));search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){refreshLibraryRows();}public void afterTextChanged(android.text.Editable e){}});LinearLayout.LayoutParams searchParams=lp(-1,dp(48));searchParams.setMargins(0,dp(14),0,dp(4));head.addView(search,searchParams);
        LinearLayout filters=row();filters.setPadding(0,dp(10),0,dp(10));Button all=filterPill("全部",!favoritesOnly);all.setOnClickListener(v->{favoritesOnly=false;refreshLibraryRows();});filters.addView(all,lp(dp(74),dp(38)));Button fav=filterPill("收藏",favoritesOnly);fav.setOnClickListener(v->{favoritesOnly=true;refreshLibraryRows();});LinearLayout.LayoutParams fp=lp(dp(74),dp(38));fp.setMargins(dp(8),0,0,0);filters.addView(fav,fp);Button count=lightPlayerButton(tracks.size()+" 首歌");count.setTextSize(12);count.setTextColor(MINT);count.setGravity(Gravity.CENTER);LinearLayout.LayoutParams cp=lp(0,dp(38),1);cp.setMargins(dp(8),0,0,0);filters.addView(count,cp);head.addView(filters);
        LinearLayout summary=card();summary.setOrientation(LinearLayout.HORIZONTAL);summary.setGravity(Gravity.CENTER_VERTICAL);summary.setPadding(dp(16),dp(11),dp(10),dp(11));summary.addView(summaryStat(String.valueOf(tracks.size()),"首歌曲"),lp(0,dp(54),1));summary.addView(divider(),lp(dp(1),dp(32)));summary.addView(summaryStat(String.valueOf(new java.util.HashSet<String>(){{for(LibraryDbHelper.Track t:tracks)add(t.album);}}.size()),"张专辑"),lp(0,dp(54),1));summary.addView(divider(),lp(dp(1),dp(32)));summary.addView(summaryStat(String.valueOf(database.favorites().size()),"首收藏"),lp(0,dp(54),1));head.addView(summary,lp(-1,dp(82)));pageHost.addView(head,lp(-1,-2));status=text(tracks.size()+" 首歌曲",12,MINT);status.setPadding(0,dp(14),0,dp(8));pageHost.addView(status,lp(-1,dp(38)));ScrollView scroll=new ScrollView(this);LinearLayout list=column();list.setTag("library-list");scroll.addView(list);pageHost.addView(scroll,lp(-1,0,1));refreshLibraryRows();
