    private void renderSettings() { ScrollView scroll=new ScrollView(this); LinearLayout body=column(); body.setPadding(0,dp(16),0,dp(16)); scroll.addView(body); pageHost.addView(scroll,lp(-1,0,1)); body.addView(section("外观")); body.addView(setting("主题模式",darkMode?"深色模式":"浅色模式",v->showThemeDialog())); body.addView(section("播放与音质")); body.addView(setting("均衡器","十段原生均衡器和预设曲线",v->showEqualizerDialog())); body.addView(setting("播放服务","MediaSession、通知栏和后台自动下一首",null)); body.addView(section("本地音乐")); body.addView(setting("扫描设备音乐","读取本地音频、封面和同名 LRC 歌词",v->scanMediaStore())); body.addView(setting("存储空间",tracks.size()+" 首歌曲 · 数据保存在本机",v->showStorageDialog())); body.addView(setting("备份与恢复","备份歌曲索引、歌单和收藏数据",v->showBackupDialog())); body.addView(section("诊断")); body.addView(setting("诊断日志","查看或清除本地播放和扫描日志",v->showLogDialog())); body.addView(section("关于 Mintune")); body.addView(setting("关于 Mintune","本地优先音乐播放器 · 版本 0.4.855",v->showAbout())); body.addView(setting("开源许可","感谢使用的开源项目",null)); }
    private void addRows(LinearLayout parent,List<LibraryDbHelper.Track> items,int limit){for(int i=0;i<Math.min(limit,items.size());i++){LibraryDbHelper.Track t=items.get(i);LinearLayout row=row();row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),dp(5),dp(4),dp(5));row.setBackground(glassBackground(SURFACE,dp(18)));row.setElevation(dp(2));ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(glassBackground(ALT,dp(12)));art.setClipToOutline(true);loadCover(art,t);row.addView(art,lp(dp(48),dp(48)));LinearLayout copy=column();copy.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(t.title,14,TEXT);title.setTypeface(null,t.uri.equals(currentUri())?android.graphics.Typeface.BOLD:android.graphics.Typeface.NORMAL);title.setMaxLines(1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);TextView meta=text(t.artist+" · "+t.album,11,MUTED);meta.setMaxLines(1);meta.setEllipsize(android.text.TextUtils.TruncateAt.END);copy.addView(title,lp(-1,dp(24)));copy.addView(meta,lp(-1,dp(20)));copy.setOnClickListener(v->play(t,tracks));LinearLayout.LayoutParams cp=lp(0,dp(50),1);cp.setMargins(dp(10),0,dp(3),0);row.addView(copy,cp);TextView duration=text(formatDuration(t.duration),10,MUTED);duration.setGravity(Gravity.CENTER);row.addView(duration,lp(dp(42),dp(42)));TextView favorite=text(t.favorite?"♥":"♡",21,t.favorite?MINT:MUTED);favorite.setGravity(Gravity.CENTER);favorite.setOnClickListener(v->{database.setFavorite(t.uri,!t.favorite);loadData();});row.addView(favorite,lp(dp(34),dp(42)));Button more=lightPlayerButton("•••");more.setTextSize(17);more.setTextColor(MUTED);more.setOnClickListener(v->showTrackMenu(t));row.addView(more,lp(dp(34),dp(42)));LinearLayout.LayoutParams rp=lp(-1,dp(64));rp.setMargins(0,0,0,dp(6));parent.addView(row,rp);}}
    private String formatDuration(long ms){long seconds=ms>10000?ms/1000:ms;return String.format(Locale.ROOT,"%d:%02d",seconds/60,seconds%60);}
    private void loadCover(ImageView target,LibraryDbHelper.Track track){if(track.coverPath!=null&&new File(track.coverPath).isFile()){target.setImageURI(android.net.Uri.fromFile(new File(track.coverPath)));return;} executor.execute(()->{android.graphics.Bitmap bitmap=CoverResolver.embedded(this,track.uri);if(bitmap!=null)runOnUiThread(()->target.setImageBitmap(bitmap));});}
    private void showTrackMenu(LibraryDbHelper.Track track){
        final android.app.Dialog dialog=new android.app.Dialog(this);
        LinearLayout panel=card(); panel.setPadding(dp(20),dp(16),dp(20),dp(16));
        TextView heading=text(track.title,19,TEXT); heading.setTypeface(null,1); panel.addView(heading);
        panel.addView(text(track.artist+" · "+track.album,13,MUTED),lp(-1,dp(30)));
        String[] actions={track.favorite?"取消收藏":"收藏","添加到歌单","播放", "查看歌词"};
        for(int i=0;i<actions.length;i++){final int action=i;Button item=button(actions[i]); item.setOnClickListener(v->{dialog.dismiss();if(action==0){database.setFavorite(track.uri,!track.favorite);loadData();}else if(action==1)showAddToPlaylist(track);else if(action==2)play(track,tracks);else showLyrics(track);});panel.addView(item,dialogGapParams());}
        Button cancel=button("取消");cancel.setOnClickListener(v->dialog.dismiss());panel.addView(cancel,dialogGapParams());
        dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);android.view.Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setDimAmount(0.55f);window.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);}dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);
    }
    private void showAddToPlaylist(LibraryDbHelper.Track track){
        List<LibraryDbHelper.Playlist> playlists=database.playlists();
        if(playlists.isEmpty()){showCreatePlaylist();return;}
        final android.app.Dialog dialog=new android.app.Dialog(this);LinearLayout panel=card();panel.setPadding(dp(20),dp(16),dp(20),dp(16));TextView heading=text("添加到歌单",19,TEXT);heading.setTypeface(null,1);panel.addView(heading);panel.addView(text(track.title,13,MUTED),lp(-1,dp(30)));
        for(LibraryDbHelper.Playlist playlist:playlists){final LibraryDbHelper.Playlist target=playlist;Button item=button(target.name+"（"+target.count+" 首）");item.setOnClickListener(v->{database.addToPlaylist(target.id,track.uri,target.count);dialog.dismiss();Toast.makeText(this,"已添加到 "+target.name,Toast.LENGTH_SHORT).show();if(page==2)switchPage(2);});panel.addView(item,dialogGapParams());}
        Button cancel=button("取消");cancel.setOnClickListener(v->dialog.dismiss());panel.addView(cancel,dialogGapParams());dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setDimAmount(.55f);dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);}
    }
    private String currentUri(){return playingIndex>=0&&playingIndex<tracks.size()?tracks.get(playingIndex).uri:"";}
